import pytest
from _pytest.python import PyCollector
from _pytest import fixtures
from types import FunctionType


class DummyConfig:
    """Minimal config stub providing getini for 'python_functions'."""
    def getini(self, name):
        if name == "python_functions":
            # default pattern from pytest.ini: test functions start with "test"
            return ["test"]
        return []


def make_collector():
    """Create a PyCollector instance without invoking its full initializer."""
    collector = object.__new__(PyCollector)
    # The only attribute used by istestfunction is `config`.
    collector.config = DummyConfig()
    return collector


def test_istestfunction_simple():
    collector = make_collector()

    def test_func():
        pass

    def not_test():
        pass

    assert collector.istestfunction(test_func, "test_func") is True
    assert collector.istestfunction(not_test, "not_test") is False


def test_istestfunction_staticmethod():
    collector = make_collector()

    class C:
        @staticmethod
        def test_static():
            pass

    # staticmethod objects need to be unwrapped; the collector does this.
    assert collector.istestfunction(C.test_static, "test_static") is True


def test_istestfunction_fixture_marker():
    collector = make_collector()

    @pytest.fixture
    def test_fixture():
        """A fixture that also starts with 'test'."""
        return 1

    # Even though the name matches the prefix, a fixture should not be
    # considered a test function.
    assert collector.istestfunction(test_fixture, "test_fixture") is False
